using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text.Json;
using LifeVerse.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace LifeVerse.Api.Modules.Platform;

public sealed record AdminDecisionRequest(string Decision, string Notes, string EvidenceJson = "{}");

public static class AdminEndpoints
{
    public static IEndpointRouteBuilder MapAdminEndpoints(this IEndpointRouteBuilder endpoints)
    {
        endpoints.MapGet("/admin", () => Results.Content(Html, "text/html; charset=utf-8"));
        var admin = endpoints.MapGroup("/api/v1/admin").WithTags("Administration").RequireAuthorization();
        admin.MapGet("/dashboard", DashboardAsync); admin.MapGet("/users", UsersAsync); admin.MapPost("/users/{id:guid}/suspend", (Guid id, HttpContext c, LifeVerseDbContext d, TimeProvider t, CancellationToken ct) => SetUserAsync(id, "suspended", c, d, t, ct)); admin.MapPost("/users/{id:guid}/ban", (Guid id, HttpContext c, LifeVerseDbContext d, TimeProvider t, CancellationToken ct) => SetUserAsync(id, "banned", c, d, t, ct)); admin.MapPost("/users/{id:guid}/reactivate", (Guid id, HttpContext c, LifeVerseDbContext d, TimeProvider t, CancellationToken ct) => SetUserAsync(id, "active", c, d, t, ct)); admin.MapPost("/users/{id:guid}/revoke-sessions", RevokeSessionsAsync);
        admin.MapGet("/islands", IslandsAsync); admin.MapPost("/islands/{id:guid}/suspend", SuspendIslandAsync); admin.MapPost("/islands/{id:guid}/resume", ResumeIslandAsync);
        admin.MapGet("/moderation", ModerationAsync); admin.MapPost("/moderation/{reportId:guid}/decide", DecideAsync); admin.MapGet("/audit", AuditAsync);
        return endpoints;
    }
    private static async Task<IResult> DashboardAsync(HttpContext c, LifeVerseDbContext db, CancellationToken ct) { if (!Admin(c, out _)) return Results.Forbid(); return Results.Ok(new { users = await db.Users.CountAsync(x => x.DeletedAt == null, ct), suspendedUsers = await db.Users.CountAsync(x => x.Status != "active" && x.DeletedAt == null, ct), islands = await db.Islands.CountAsync(x => x.DeletedAt == null, ct), activeIslands = await db.Islands.CountAsync(x => x.RuntimeState == "running" && x.DeletedAt == null, ct), instances = await db.ServerInstances.CountAsync(x => x.StoppedAt == null, ct), objects = await db.BuildObjects.CountAsync(x => x.DeletedAt == null, ct), assets = await db.Assets.CountAsync(x => x.DeletedAt == null, ct), pendingReports = await db.SocialReports.CountAsync(x => x.Status == "open", ct), generatedAt = DateTimeOffset.UtcNow }); }
    private static async Task<IResult> UsersAsync(string? q, HttpContext c, LifeVerseDbContext db, CancellationToken ct) { if (!Admin(c, out _)) return Results.Forbid(); var query = db.Users.AsNoTracking().Where(x => x.DeletedAt == null); if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.Username.ToLower().Contains(q.ToLower()) || x.Email.ToLower().Contains(q.ToLower())); return Results.Ok(await query.OrderBy(x => x.Username).Take(100).Select(x => new { x.Id, x.Username, x.Email, x.Status, x.CreatedAt, sessions = x.Sessions.Count(s => s.RevokedAt == null && s.ExpiresAt > DateTimeOffset.UtcNow) }).ToListAsync(ct)); }
    private static async Task<IResult> SetUserAsync(Guid id, string status, HttpContext c, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!Admin(c, out var admin)) return Results.Forbid(); var user = await db.Users.Include(x => x.Sessions).SingleOrDefaultAsync(x => x.Id == id && x.DeletedAt == null, ct); if (user is null) return Results.NotFound(); user.Status = status; if (status != "active") foreach (var s in user.Sessions.Where(x => x.RevokedAt == null)) s.RevokedAt = clock.GetUtcNow(); await Audit(db, admin, $"user_{status}", "user", id, clock.GetUtcNow(), ct); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> RevokeSessionsAsync(Guid id, HttpContext c, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!Admin(c, out var admin)) return Results.Forbid(); var sessions = await db.Sessions.Where(x => x.UserId == id && x.RevokedAt == null).ToListAsync(ct); var now = clock.GetUtcNow(); foreach (var s in sessions) s.RevokedAt = now; await Audit(db, admin, "revoke_sessions", "user", id, now, ct); await db.SaveChangesAsync(ct); return Results.Ok(new { revoked = sessions.Count }); }
    private static async Task<IResult> IslandsAsync(HttpContext c, LifeVerseDbContext db, CancellationToken ct) { if (!Admin(c, out _)) return Results.Forbid(); return Results.Ok(await db.Islands.AsNoTracking().Where(x => x.DeletedAt == null).OrderByDescending(x => x.UpdatedAt).Take(200).Select(x => new { x.Id, x.Name, x.OwnerUserId, x.RuntimeState, x.MaxPlayers, x.UpdatedAt }).ToListAsync(ct)); }
    private static async Task<IResult> SuspendIslandAsync(Guid id, HttpContext c, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) => await SetIslandState(id, "suspended", c, db, clock, ct);
    private static async Task<IResult> ResumeIslandAsync(Guid id, HttpContext c, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) => await SetIslandState(id, "running", c, db, clock, ct);
    private static async Task<IResult> SetIslandState(Guid id, string state, HttpContext c, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!Admin(c, out var admin)) return Results.Forbid(); var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == id && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); island.RuntimeState = state; island.UpdatedAt = clock.GetUtcNow(); await Audit(db, admin, $"island_{state}", "island", id, island.UpdatedAt, ct); await db.SaveChangesAsync(ct); return Results.Ok(new { island.Id, island.RuntimeState }); }
    private static async Task<IResult> ModerationAsync(HttpContext c, LifeVerseDbContext db, CancellationToken ct) { if (!Admin(c, out _)) return Results.Forbid(); return Results.Ok(await db.SocialReports.AsNoTracking().Where(x => x.Status == "open").OrderBy(x => x.CreatedAt).Take(200).ToListAsync(ct)); }
    private static async Task<IResult> DecideAsync(Guid reportId, AdminDecisionRequest request, HttpContext c, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!Admin(c, out var admin)) return Results.Forbid(); if (request.Decision is not ("dismissed" or "actioned" or "escalated")) return Results.BadRequest(); var report = await db.SocialReports.SingleOrDefaultAsync(x => x.Id == reportId, ct); if (report is null) return Results.NotFound(); report.Status = request.Decision; var now = clock.GetUtcNow(); db.ModerationCases.Add(new ModerationCase { Id = Guid.NewGuid(), ReportId = reportId, ReviewerUserId = admin, Decision = request.Decision, Notes = request.Notes[..Math.Min(4000, request.Notes.Length)], EvidenceJson = request.EvidenceJson, CreatedAt = now }); await Audit(db, admin, "moderation_decision", "report", reportId, now, ct); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> AuditAsync(HttpContext c, LifeVerseDbContext db, CancellationToken ct) { if (!Admin(c, out _)) return Results.Forbid(); return Results.Ok(await db.AdminAudits.AsNoTracking().OrderByDescending(x => x.CreatedAt).Take(200).ToListAsync(ct)); }
    private static bool Admin(HttpContext context, out Guid userId) { userId = Guid.Empty; if (!Guid.TryParse(context.User.FindFirstValue(JwtRegisteredClaimNames.Sub), out userId)) return false; var ids = (Environment.GetEnvironmentVariable("LIFEVERSE_ADMIN_USER_IDS") ?? string.Empty).Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries); var mfa = Environment.GetEnvironmentVariable("LIFEVERSE_ADMIN_MFA_TOKEN"); return ids.Contains(userId.ToString(), StringComparer.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(mfa) && string.Equals(context.Request.Headers["X-Admin-MFA"].ToString(), mfa, StringComparison.Ordinal);
    }
    private static async Task Audit(LifeVerseDbContext db, Guid admin, string action, string targetType, Guid targetId, DateTimeOffset now, CancellationToken ct) { db.AdminAudits.Add(new AdminAudit { Id = Guid.NewGuid(), AdminUserId = admin, Action = action, TargetType = targetType, TargetId = targetId, MetadataJson = JsonSerializer.Serialize(new { correlationId = Guid.NewGuid() }), CreatedAt = now }); await db.SaveChangesAsync(ct); }
    private const string Html = "<!doctype html><html><head><meta charset='utf-8'><title>LifeVerse Admin</title><style>body{font:14px sans-serif;background:#101522;color:#eee;margin:2rem}button{padding:.5rem}pre{background:#182235;padding:1rem}</style></head><body><h1>LifeVerse Operations</h1><button onclick='load()'>Atualizar</button><pre id='out'>Use um token administrativo e o header X-Admin-MFA.</pre><script>async function load(){let r=await fetch('/api/v1/admin/dashboard',{headers:{Authorization:'Bearer '+prompt('Access token'), 'X-Admin-MFA':prompt('MFA token')}});document.querySelector('#out').textContent=await r.text()}</script></body></html>";
}
